// @FIGURE_CODE_BEGIN
// x-axis → thin black cylinder/cone arrow from O along +x, label x
// y-axis → thin black cylinder/cone arrow from O along +y, label y
// z-axis → thin black cylinder/cone arrow from O along +z, label z
// origin O → small black point label O
// main r vector → heavy blue cylinder/cone arrow from O to P
// point P → black sphere at endpoint of r, label P
// force F → heavy red cylinder/cone arrow from P, angle theta from r in xy-plane
// torque tau → heavy orange cylinder/cone arrow from P along +z, length proportional to sin(theta)
// r extension → dark dashed line along r direction beyond P
// F line of action → dark dashed line through P along F direction
// theta arcs → two black circular arc line geometries centered at P in xy-plane
// r_perp → thin black moment-arm line from O to foot on force line
// right-angle marker → small black square at moment-arm foot
// r_perp label → CSS label beside perpendicular segment
// vector labels → CSS labels for r, F, tau, theta
// stylized hand → tan semi-transparent palm/fingers/thumb low-relief mesh group
// secondary r arrow → heavy blue arrow beside hand parallel to main r
// secondary F arrow → heavy red arrow beside hand following theta
// curl arrows → black curved arrows around hand showing rotation from r toward F

const physToWorld = (x, y, z = 0) => new THREE.Vector3(y, z, x);
const Ophys = new THREE.Vector3(0, 0, 0);
const Pphys = new THREE.Vector3(-0.95, 2.7, 0);
const rPhys = Pphys.clone();
const rLen = Math.hypot(rPhys.x, rPhys.y);
const rDir = new THREE.Vector3(rPhys.x / rLen, rPhys.y / rLen, 0);
const rAng = Math.atan2(rDir.y, rDir.x);
const blue = 0x174a7a;
const red = 0xd63b3b;
const orange = 0xf28a1a;
const dark = 0x222222;

function W(v) { return physToWorld(v.x, v.y, v.z || 0); }

function makeMat(color, opacity = 1) {
  return new THREE.MeshBasicMaterial({ color, transparent: opacity < 1, opacity, depthWrite: opacity >= 0.7 });
}

function makeLineMat(color, dashed = false, opacity = 1) {
  const opts = { color, transparent: opacity < 1, opacity };
  return dashed ? new THREE.LineDashedMaterial({ ...opts, dashSize: 0.12, gapSize: 0.07 }) : new THREE.LineBasicMaterial(opts);
}

function setObjOpacity(obj, opacity) {
  obj.traverse(o => {
    if (o.material) {
      const mats = Array.isArray(o.material) ? o.material : [o.material];
      mats.forEach(m => {
        m.transparent = opacity < 1;
        m.opacity = opacity;
        m.depthWrite = opacity >= 0.7;
        m.needsUpdate = true;
      });
    }
  });
}

function makeArrow(start, end, color, radius = 0.025, headLen = 0.18, headRadius = 0.075, opacity = 1) {
  const group = new THREE.Group();
  const mat = makeMat(color, opacity);
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, 1, 20), mat);
  const head = new THREE.Mesh(new THREE.ConeGeometry(headRadius, 1, 24), mat);
  group.add(shaft, head);
  group.userData.shaft = shaft;
  group.userData.head = head;
  group.userData.headLen = headLen;
  group.userData.update = (a, b) => updateArrow(group, a, b);
  updateArrow(group, start, end);
  scene.add(group);
  return group;
}

function updateArrow(group, start, end) {
  const dir = end.clone().sub(start);
  const len = Math.max(dir.length(), 0.0001);
  const shaftLen = Math.max(len - group.userData.headLen, len * 0.45);
  const headLen = Math.min(group.userData.headLen, len * 0.55);
  group.position.copy(start);
  group.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  const shaft = group.userData.shaft;
  const head = group.userData.head;
  shaft.scale.set(1, shaftLen, 1);
  shaft.position.set(0, shaftLen / 2, 0);
  head.scale.set(1, headLen, 1);
  head.position.set(0, shaftLen + headLen / 2, 0);
}

function makeLine(points, color = dark, dashed = false, opacity = 1) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const line = new THREE.Line(geom, makeLineMat(color, dashed, opacity));
  if (dashed) line.computeLineDistances();
  scene.add(line);
  return line;
}

function updateLine(line, points) {
  const old = line.geometry;
  line.geometry = new THREE.BufferGeometry().setFromPoints(points);
  old.dispose();
  if (line.material.isLineDashedMaterial) line.computeLineDistances();
}

function arcPoints(centerPhys, radius, a0, a1, z = 0, n = 36) {
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const t = a0 + (a1 - a0) * i / n;
    pts.push(W(new THREE.Vector3(centerPhys.x + radius * Math.cos(t), centerPhys.y + radius * Math.sin(t), z)));
  }
  return pts;
}

function makeArcArrow(centerPhys, radius, a0, a1, z, color, opacity = 1) {
  const group = new THREE.Group();
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(arcPoints(centerPhys, radius, a0, a1, z, 44)), makeLineMat(color, false, opacity));
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.055, 0.14, 18), makeMat(color, opacity));
  group.add(line, head);
  scene.add(group);
  group.userData.line = line;
  group.userData.head = head;
  group.userData.update = (aa0, aa1) => {
    updateLine(line, arcPoints(centerPhys, radius, aa0, aa1, z, 44));
    const endPhys = new THREE.Vector3(centerPhys.x + radius * Math.cos(aa1), centerPhys.y + radius * Math.sin(aa1), z);
    const tanPhys = new THREE.Vector3(-Math.sin(aa1), Math.cos(aa1), 0).multiplyScalar(aa1 >= aa0 ? 1 : -1);
    const end = W(endPhys);
    const ahead = W(endPhys.clone().add(tanPhys.multiplyScalar(0.12)));
    updateArrowLikeCone(head, end, ahead);
  };
  group.userData.update(a0, a1);
  return group;
}

function updateArrowLikeCone(cone, start, end) {
  const dir = end.clone().sub(start).normalize();
  cone.position.copy(start.clone().add(dir.clone().multiplyScalar(0.035)));
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
}

const geometricGroup = new THREE.Group();
const handGroup = new THREE.Group();
scene.add(geometricGroup, handGroup);

const xAxis = makeArrow(W(new THREE.Vector3(0,0,0)), W(new THREE.Vector3(3.2,0,0)), 0x000000, 0.006, 0.13, 0.04);
const yAxis = makeArrow(W(new THREE.Vector3(0,0,0)), W(new THREE.Vector3(0,4.4,0)), 0x000000, 0.006, 0.13, 0.04);
const zAxis = makeArrow(W(new THREE.Vector3(0,0,0)), W(new THREE.Vector3(0,0,3.8)), 0x000000, 0.006, 0.13, 0.04);

const originDot = new THREE.Mesh(new THREE.SphereGeometry(0.035, 16, 12), makeMat(0x000000));
originDot.position.copy(W(Ophys));
scene.add(originDot);

const rArrow = makeArrow(W(Ophys), W(Pphys), blue, 0.035, 0.24, 0.105);
const pDot = new THREE.Mesh(new THREE.SphereGeometry(0.055, 20, 14), makeMat(0x000000));
pDot.position.copy(W(Pphys));
scene.add(pDot);

const fArrow = makeArrow(W(Pphys), W(new THREE.Vector3(0, 0, 0)), red, 0.035, 0.24, 0.105);
const tauArrow = makeArrow(W(Pphys), W(new THREE.Vector3(Pphys.x, Pphys.y, 1)), orange, 0.035, 0.24, 0.105);

const rDash = makeLine([W(Pphys.clone().sub(rDir.clone().multiplyScalar(0.15))), W(Pphys.clone().add(rDir.clone().multiplyScalar(2.25)))], dark, true);
const fDash = makeLine([W(Pphys), W(Pphys)], dark, true);
const momentArm = makeLine([W(Ophys), W(Pphys)], 0x000000, false);
const rightSquare = makeLine([W(Pphys), W(Pphys)], 0x000000, false);
const thetaArc1 = makeLine(arcPoints(Pphys, 0.35, rAng, rAng + THREE.MathUtils.degToRad(50)), 0x000000);
const thetaArc2 = makeLine(arcPoints(Pphys, 0.48, rAng + Math.PI, rAng + Math.PI + THREE.MathUtils.degToRad(50)), 0x000000);

geometricGroup.add(rDash, fDash, momentArm, rightSquare, thetaArc1, thetaArc2);

const palmMat = new THREE.MeshBasicMaterial({ color: 0xf1c58d, transparent: true, opacity: 0.28, depthWrite: false, side: THREE.DoubleSide });
const palm = new THREE.Mesh(new THREE.SphereGeometry(0.34, 28, 16), palmMat);
palm.scale.set(1.15, 0.32, 0.72);
palm.position.copy(W(new THREE.Vector3(1.55, 0.95, -0.42)));
handGroup.add(palm);

function addFinger(basePhys, len, angle, width, z = -0.37) {
  const start = W(new THREE.Vector3(basePhys.x, basePhys.y, z));
  const endPhys = new THREE.Vector3(basePhys.x + len * Math.cos(angle), basePhys.y + len * Math.sin(angle), z + 0.02);
  const end = W(endPhys);
  const finger = makeArrow(start, end, 0xf1c58d, width, 0.001, width, 0.33);
  finger.userData.head.visible = false;
  handGroup.add(finger);
  return finger;
}
addFinger(new THREE.Vector3(1.35, 0.83, 0), 0.62, rAng + 0.18, 0.055);
addFinger(new THREE.Vector3(1.50, 0.91, 0), 0.68, rAng + 0.04, 0.052);
addFinger(new THREE.Vector3(1.66, 0.98, 0), 0.61, rAng - 0.10, 0.048);
addFinger(new THREE.Vector3(1.82, 1.03, 0), 0.48, rAng - 0.24, 0.043);
addFinger(new THREE.Vector3(1.35, 0.72, 0), 0.55, rAng + 1.05, 0.06, -0.39);

const secRStart = new THREE.Vector3(1.1, 0.84, -0.62);
const secREnd = secRStart.clone().add(rDir.clone().multiplyScalar(1.7));
const secRArrow = makeArrow(W(secRStart), W(secREnd), blue, 0.035, 0.22, 0.10);
const secFStart = secRStart.clone().add(rDir.clone().multiplyScalar(0.58));
const secFArrow = makeArrow(W(secFStart), W(secFStart), red, 0.035, 0.22, 0.10);
handGroup.add(secRArrow, secFArrow);

const curl1 = makeArcArrow(new THREE.Vector3(1.2, 1.42, -0.25), 0.28, -0.85, 0.75, -0.25, 0x000000, 0.9);
const curl2 = makeArcArrow(new THREE.Vector3(1.82, 1.72, -0.35), 0.22, -0.65, 0.95, -0.35, 0x000000, 0.9);
handGroup.add(curl1, curl2);

registerInteractive(rArrow, {
  title: 'Position vector r',
  tooltip: 'Position vector from O to P',
  body: 'The vector r locates the point of application of the force relative to the origin. Its perpendicular distance to the line of action controls torque magnitude.'
});
registerInteractive(fArrow, {
  title: 'Force vector F',
  tooltip: 'Applied force at P',
  body: 'Changing θ rotates the force in the r–F plane. Only the component perpendicular to r contributes to torque.'
});
registerInteractive(tauArrow, {
  title: 'Torque vector τ',
  tooltip: 'τ = r × F',
  body: 'The orange vector is perpendicular to the plane of r and F. Its length is proportional to |r||F|sinθ.'
});
registerInteractive(momentArm, {
  title: 'Moment arm r⊥',
  tooltip: 'Perpendicular moment arm',
  body: 'r⊥ is the shortest distance from the origin to the force line of action. Here r⊥ = |r|sinθ.'
});

