function tweenTheta(to, duration = 650) {
  const from = thetaDeg;
  const t0 = performance.now();
  function step(now) {
    const u = Math.min(1, (now - t0) / duration);
    const e = u * u * (3 - 2 * u);
    thetaDeg = from + (to - from) * e;
    thetaSlider.value = Math.round(thetaDeg / 5) * 5;
    updatePhysics();
    if (u < 1) requestAnimationFrame(step);
    else {
      thetaDeg = to;
      thetaSlider.value = to;
      updatePhysics();
    }
  }
  requestAnimationFrame(step);
}

