const physToWorld = (x, y, z = 0) => new THREE.Vector3(y, z, x);
const W = (v) => physToWorld(v.x, v.y, v.z || 0);
const blue = 0x174a7a;
const red = 0xd63b3b;
const orange = 0xf28a1a;
const dark = 0x222222;
