const Pphys = new THREE.Vector3(-0.95, 2.7, 0);
const rPhys = Pphys.clone();
const rLen = Math.hypot(rPhys.x, rPhys.y);
const rDir = new THREE.Vector3(rPhys.x / rLen, rPhys.y / rLen, 0);
const rAng = Math.atan2(rDir.y, rDir.x);

function vecHTML(s) {
  return `<span style="display:inline-flex;flex-direction:column;align-items:center;line-height:.72;vertical-align:middle"><span style="font-size:.72em;height:.62em">&rarr;</span><i>${s}</i></span>`;
}

function makeMat(color, opacity = 1) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    depthWrite: opacity >= 0.65,
    side: THREE.DoubleSide
  });
}

function makeLineMat(color, dashed = false, opacity = 1) {
  const opts = { color, transparent: opacity < 1, opacity, depthWrite: opacity >= 0.8 };
  return dashed ? new THREE.LineDashedMaterial({ ...opts, dashSize: 0.13, gapSize: 0.075 }) : new THREE.LineBasicMaterial(opts);
}

function setObjOpacity(obj, opacity) {
  obj.traverse(o => {
    if (!o.material) return;
    const mats = Array.isArray(o.material) ? o.material : [o.material];
    mats.forEach(m => {
      m.transparent = opacity < 1;
      m.opacity = opacity;
      m.depthWrite = opacity >= 0.65;
      m.needsUpdate = true;
    });
  });
}

function updateArrow(group, start, end) {
  const dir = end.clone().sub(start);
  const len = Math.max(dir.length(), 0.0001);
  const headLen = Math.min(group.userData.headLen, len * 0.56);
  const shaftLen = Math.max(len - headLen, len * 0.38);
  group.position.copy(start);
  group.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  group.userData.shaft.scale.set(1, shaftLen, 1);
  group.userData.shaft.position.set(0, shaftLen / 2, 0);
  group.userData.head.scale.set(1, headLen, 1);
  group.userData.head.position.set(0, shaftLen + headLen / 2, 0);
}

function makeArrow(start, end, color, radius = 0.025, headLen = 0.18, headRadius = 0.075, opacity = 1) {
  const group = new THREE.Group();
  const mat = makeMat(color, opacity);
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, 1, 24), mat);
  const head = new THREE.Mesh(new THREE.ConeGeometry(headRadius, 1, 28), mat);
  group.add(shaft, head);
  group.userData.shaft = shaft;
  group.userData.head = head;
  group.userData.headLen = headLen;
  group.userData.update = (a, b) => updateArrow(group, a, b);
  updateArrow(group, start, end);
  scene.add(group);
  return group;
}

function updateConeDirection(cone, start, end) {
  const dir = end.clone().sub(start).normalize();
  cone.position.copy(start.clone().add(dir.clone().multiplyScalar(0.045)));
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
}

function makeLine(points, color = dark, dashed = false, opacity = 1) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const line = new THREE.Line(geom, makeLineMat(color, dashed, opacity));
  if (dashed) line.computeLineDistances();
  scene.add(line);
  return line;
}

function updateLine(line, points) {
  const old = line.geometry;
  line.geometry = new THREE.BufferGeometry().setFromPoints(points);
  old.dispose();
  if (line.material.isLineDashedMaterial) line.computeLineDistances();
}

function arcPoints(centerPhys, radius, a0, a1, z = 0, n = 44) {
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const t = a0 + (a1 - a0) * i / n;
    pts.push(W(new THREE.Vector3(centerPhys.x + radius * Math.cos(t), centerPhys.y + radius * Math.sin(t), z)));
  }
  return pts;
}

function makeArcArrow(centerPhys, radius, a0, a1, z, color, opacity = 1) {
  const group = new THREE.Group();
  const line = new THREE.Line(new THREE.BufferGeometry(), makeLineMat(color, false, opacity));
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.06, 0.14, 20), makeMat(color, opacity));
  group.add(line, head);
  scene.add(group);
  group.userData.line = line;
  group.userData.head = head;
  group.userData.update = (aa0, aa1) => {
    updateLine(line, arcPoints(centerPhys, radius, aa0, aa1, z, 48));
    const endPhys = new THREE.Vector3(centerPhys.x + radius * Math.cos(aa1), centerPhys.y + radius * Math.sin(aa1), z);
    const tangent = new THREE.Vector3(-Math.sin(aa1), Math.cos(aa1), 0).multiplyScalar(aa1 >= aa0 ? 1 : -1);
    updateConeDirection(head, W(endPhys), W(endPhys.clone().add(tangent.multiplyScalar(0.12))));
  };
  group.userData.update(a0, a1);
  return group;
}

function makeCapsuleSegment(start, end, radius, color, opacity = 1) {
  const group = new THREE.Group();
  const mat = makeMat(color, opacity);
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, 1, 18), mat);
  const capA = new THREE.Mesh(new THREE.SphereGeometry(radius, 18, 10), mat);
  const capB = new THREE.Mesh(new THREE.SphereGeometry(radius, 18, 10), mat);
  group.add(shaft, capA, capB);
  const dir = end.clone().sub(start);
  const len = Math.max(dir.length(), 0.0001);
  group.position.copy(start);
  group.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  shaft.scale.set(1, len, 1);
  shaft.position.set(0, len / 2, 0);
  capA.position.set(0, 0, 0);
  capB.position.set(0, len, 0);
  scene.add(group);
  return group;
}

