function addFinger(basePhys, len, angle, radius, z = -0.43, spread = 0) {
  const startP = new THREE.Vector3(basePhys.x, basePhys.y, z);
  const midP = new THREE.Vector3(basePhys.x + len * 0.52 * Math.cos(angle), basePhys.y + len * 0.52 * Math.sin(angle), z + spread);
  const endP = new THREE.Vector3(basePhys.x + len * Math.cos(angle + 0.05), basePhys.y + len * Math.sin(angle + 0.05), z + spread * 1.4);
  const a = makeCapsuleSegment(W(startP), W(midP), radius, tan, 0.68);
  const b = makeCapsuleSegment(W(midP), W(endP), radius * 0.88, tan, 0.68);
  handShapeGroup.add(a, b);
  return [a, b];
}

addFinger(new THREE.Vector3(1.34, 0.58, 0), 0.76, rAng + 0.21, 0.055, -0.39, 0.015);
