function fDirFromTheta(deg) {
  const a = rAng + THREE.MathUtils.degToRad(deg);
  return new THREE.Vector3(Math.cos(a), Math.sin(a), 0);
}

function updatePhysics() {
  const fDir = fDirFromTheta(thetaDeg);
  const Flen = 1.65;
  const Fend = Pphys.clone().add(fDir.clone().multiplyScalar(Flen));
  updateArrow(fArrow, W(Pphys), W(Fend));

  const sine = Math.sin(THREE.MathUtils.degToRad(thetaDeg));
  const tauLen = Math.max(0.045, 1.45 * Math.max(0, sine));
  const tauEnd = Pphys.clone().add(new THREE.Vector3(0, 0, tauLen));
  updateArrow(tauArrow, W(Pphys), W(tauEnd));

  updateLine(rDash, [
    W(Pphys.clone().sub(rDir.clone().multiplyScalar(0.22))),
    W(Pphys.clone().add(rDir.clone().multiplyScalar(2.25)))
  ]);
  updateLine(fDash, [
    W(Pphys.clone().sub(fDir.clone().multiplyScalar(1.05))),
    W(Pphys.clone().add(fDir.clone().multiplyScalar(2.35)))
  ]);

  const footScalar = -Pphys.dot(fDir);
  const Q = Pphys.clone().add(fDir.clone().multiplyScalar(footScalar));
  updateLine(momentArm, [W(Ophys), W(Q)]);

  const qToO = Ophys.clone().sub(Q);
  const qToODir = qToO.length() > 0.001 ? qToO.normalize() : new THREE.Vector3(-fDir.y, fDir.x, 0);
  const sq = 0.18;
  const p0 = Q.clone();
  const p1 = Q.clone().add(qToODir.clone().multiplyScalar(sq));
  const p2 = p1.clone().add(fDir.clone().multiplyScalar(sq));
  const p3 = Q.clone().add(fDir.clone().multiplyScalar(sq));
  updateLine(rightSquare, [W(p0), W(p1), W(p2), W(p3), W(p0)]);

  const a0 = rAng;
  const a1 = rAng + THREE.MathUtils.degToRad(thetaDeg);
  updateLine(thetaArc1, arcPoints(Pphys, 0.35, a0, a1, 0.02, 44));
  updateLine(thetaArc2, arcPoints(Pphys, 0.48, a0 + Math.PI, a1 + Math.PI, 0.02, 44));

  const secFEnd = secFStart.clone().add(fDir.clone().multiplyScalar(1.2));
  updateArrow(secFArrow, W(secFStart), W(secFEnd));
  const curlEnd = rAng - 0.38 + THREE.MathUtils.degToRad(Math.max(25, Math.min(thetaDeg, 120)));
  curl1.userData.update(rAng - 0.38, curlEnd);
  curl2.userData.update(rAng - 0.18, rAng - 0.18 + THREE.MathUtils.degToRad(Math.max(25, Math.min(thetaDeg, 120))));

  if (lblF) lblF.pos.copy(W(Pphys.clone().add(fDir.clone().multiplyScalar(1.22)).add(new THREE.Vector3(0, 0, 0.09))));
  if (lblTau) lblTau.pos.copy(W(Pphys.clone().add(new THREE.Vector3(0.06, 0.06, tauLen + 0.28))));
  if (lblTheta1) lblTheta1.pos.copy(W(Pphys.clone().add(new THREE.Vector3(
    0.48 * Math.cos((a0 + a1) / 2),
    0.48 * Math.sin((a0 + a1) / 2),
    0.06
  ))));
  if (lblTheta2) lblTheta2.pos.copy(W(Pphys.clone().add(new THREE.Vector3(
    0.64 * Math.cos((a0 + a1) / 2 + Math.PI),
    0.64 * Math.sin((a0 + a1) / 2 + Math.PI),
    0.06
  ))));
  if (lblRperp) lblRperp.pos.copy(W(Q.clone().multiplyScalar(0.48).add(new THREE.Vector3(0.03, -0.02, 0.07))));
  if (lblSecF) lblSecF.pos.copy(W(secFEnd.clone().add(new THREE.Vector3(0.08, 0.03, 0.02))));

  document.getElementById('thetaValue').innerHTML = `${Math.round(thetaDeg)}&deg;`;
}

updatePhysics();

